import { logInfo } from "zttp:log";

structural LoggedResponse<T> = Proof<T, "deterministic" | "state_isolated">;

export function handler(req: Request): LoggedResponse<Response> {
  const at = Date.now();
  logInfo("served request", { at: at });
  return Response.json({ ok: true });
}
```

Note `at` has no type annotation on const — is that allowed? The example has `const at = Date.now();` so yes (BindingDecl allows optional type). ZTS604 canonical rule applies to let→const; const is fine.

